-- RK01 global/shared technical knowledge. No tenant records or private workshop identifiers are referenced.
CREATE TABLE repair_jobs (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, system text NOT NULL, subsystem text NOT NULL, name text NOT NULL,
 description text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE repair_part_roles (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, category text NOT NULL CHECK(category IN ('COMPONENT','CONSUMABLE')), active boolean NOT NULL DEFAULT true
);
CREATE TABLE repair_vehicle_applicabilities (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, make text NOT NULL, model text NOT NULL, generation text, variant text, engine_code text NOT NULL,
 production_from date, production_to date, restrictions text, CHECK(production_to IS NULL OR production_from IS NULL OR production_to>=production_from)
);
CREATE TABLE repair_bom_edges (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, applicability_id uuid NOT NULL REFERENCES repair_vehicle_applicabilities(id),
 repair_job_id uuid NOT NULL REFERENCES repair_jobs(id), part_role_id uuid NOT NULL REFERENCES repair_part_roles(id),
 item_kind text NOT NULL CHECK(item_kind IN ('PART_ROLE','CONSUMABLE')), quantity numeric(10,3) CHECK(quantity IS NULL OR quantity>0),
 requirement_type text NOT NULL CHECK(requirement_type IN ('REQUIRED','RECOMMENDED','CONDITIONAL','OPTIONAL')),
 bom_classification text NOT NULL CHECK(bom_classification IN ('EXPLICIT_BOM','DERIVED_FROM_KIT','MULTI_SOURCE_BOM','TECHNICAL_RULE')),
 confidence_state text NOT NULL CHECK(confidence_state IN ('VERIFIED_OEM','VERIFIED_MANUFACTURER','MULTI_SOURCE_VERIFIED','DERIVED_FROM_KIT','COMMUNITY_SUPPORTED','INFERRED','UNKNOWN')),
 condition text, replace_once boolean NOT NULL DEFAULT false, side text, axle text, position text, notes text,
 UNIQUE(applicability_id,repair_job_id,part_role_id,code)
);
CREATE TABLE repair_bom_evidence (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), edge_id uuid NOT NULL REFERENCES repair_bom_edges(id) ON DELETE CASCADE, source text NOT NULL, evidence_reference text NOT NULL,
 source_type text NOT NULL, checked_at date NOT NULL, confidence_state text NOT NULL CHECK(confidence_state IN ('VERIFIED_OEM','VERIFIED_MANUFACTURER','MULTI_SOURCE_VERIFIED','DERIVED_FROM_KIT','COMMUNITY_SUPPORTED','INFERRED','UNKNOWN')),
 reuse_status text NOT NULL, notes text, source_version text, UNIQUE(edge_id,source,evidence_reference)
);

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['repair_jobs','repair_part_roles','repair_vehicle_applicabilities','repair_bom_edges','repair_bom_evidence'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY global_repair_knowledge_read ON %I FOR SELECT TO bibendia_api USING (true)',t);
 EXECUTE format('CREATE POLICY repair_knowledge_migrator_write ON %I FOR ALL TO bibendia_migrator USING (true) WITH CHECK (true)',t);
END LOOP; END $$;
GRANT SELECT ON repair_jobs,repair_part_roles,repair_vehicle_applicabilities,repair_bom_edges,repair_bom_evidence TO bibendia_api;

